python - <<'PY'
import json
from pathlib import Path

data=json.loads(Path('benchmark/source_data.json').read_text())
# compute crossover where solar/wind < min fossil low? use min(gas_ccgt_low, coal_low) in that year; fossil data is biennial.
foss={row['year']:row for row in data['fossil_fuel_lcoe_range']['data']}
min_low={y:min(foss[y]['gas_ccgt_low'], foss[y]['coal_low']) for y in foss}
# create year->min_low by carrying forward to next year until next fossil row
years=range(2010,2025)
min_low_year={}
prev=None
for y in years:
    if y in min_low:
        prev=min_low[y]
    min_low_year[y]=prev

lcoe={row['year']:row for row in data['lcoe_trends']['data']}
for tech in ['solar_pv','onshore_wind']:
    cross=None
    for y in years:
        if min_low_year[y] is None: continue
        if lcoe[y][tech] < min_low_year[y]:
            cross=y
            break
    print(tech,'cross',cross,'lcoe',lcoe[cross][tech],'min_fossil_low',min_low_year[cross])
PY

